mapper.select:
SELECT d.id, d.parent_id, d.name, d.code, d.leader_id, d.status, d.sort_order, d.create_time, d.update_time, lu.nickname AS leader_name, (SELECT COUNT(*) FROM sys_dept_user sdu WHERE sdu.dept_id = d.id) AS user_count FROM sys_dept d LEFT JOIN sys_user lu ON lu.id = d.leader_id
AND d.status = #{query.status}
ORDER BY d.sort_order, d.id
